from pathlib import Path
import json, re, html
ROOT=Path(__file__).resolve().parent
W=ROOT.parent
read=lambda p: json.loads(p.read_text(encoding='utf-8'))
draft=read(W/'UXDraft20261012/slide_draft.json')
research=read(W/'UXDraft20261012/research_sources.json')
visuals=read(W/'UXDraft20261012/visual_sources.json')['visuals']
E=lambda s:html.escape(str(s),quote=True)
A=lambda u,t:f'<a href="{E(u)}">{E(t)}</a>'
sources=[]
for r in research['sources']: sources.append(dict(r))
for key,url in draft['sources'].items():
    if not any(x['url']==url for x in sources): sources.append(dict(id='UX-'+key,category='UX / professional examples',title=key.replace('_',' ').title(),url=url,use='Supports the original slide draft; see linked slide for the specific teaching application.',status='Carried forward from the 12 October source review; no new full-video review.'))
extra=[
('QT1','Qt technical reference','Qt for Python tutorials','https://doc.qt.io/qtforpython-6/tutorials/','Buttons, signals/slots, dialogs, and tables: implementation examples for UX decisions.'),
('QT2','Qt technical reference','Qt layout management','https://doc.qt.io/qtforpython-6.8/overviews/qtwidgets-layout.html','Label/field alignment and resizing; use to explain grouping.'),
('QT3','Qt technical reference','QLineEdit input validation','https://doc.qt.io/qtforpython-6/PySide6/QtWidgets/QLineEdit.html','Input constraints; distinguish syntax validation from a valid asset operation.'),
('C1','Optional paid study','Karol: Unreal Engine Blueprint Automation · 8h 35m','https://www.udemy.com/course/unreal-engine-blueprint-automation/','Best companion for editor actions, data-driven tools, and Editor Utility Widgets.'),
('C2','Optional paid study','Daniel Gakwaya: Qt for Python fundamentals · 12h 1m','https://www.udemy.com/course/qt-for-python-pyside6-gui-for-beginners/','Selective preparation: widgets, layouts, Designer, dialogs. Not required viewing.'),
('C3','Optional paid study','Thomas Harle: Blueprint Tools for Artists · 7h 2m','https://www.udemy.com/course/unreal-5-blueprint-tools-for-artists/','Later scene-building tools, exposed parameters, generators, and splines.'),
('C4','Optional paid study','Chris Nodder: Paper Prototyping · 24m','https://www.linkedin.com/learning/ux-design-6-paper-prototyping','Short preparation for layout sketching and paper interaction tests.'),
('C5','Optional paid study','Chris Nodder: Usability Testing · 1h 29m','https://www.linkedin.com/learning/ux-foundations-usability-testing','Moderation, observation, and interpreting findings.'),
('C6','Free course','Qt Academy course catalog','https://www.qt.io/academy/course-catalog','Getting Started with Qt for Python: 30-minute orientation; authoring may require account/setup.'),
('C7','Optional paid study','Unreal Engine: Creating Widgets for UI · 3h 31m','https://www.udemy.com/course/unreal-engine-creating-widgets-for-ui/','Game-menu examples; transferable widget implementation skills.'),
('C8','Optional paid study','Automation using Editor Utility Widgets · 6h 51m','https://www.udemy.com/course/unreal-engine-5-blueprint-prefabs-editor-utility-widgets/','Prefab/data-asset project; secondary alternative to Karol.'),
('C9','Optional paid study','Unreal Materials: Build Real Shader Effects · 3h 10m','https://www.udemy.com/course/unreal-materials/','Future shader block; content an automation tool might configure.')]
for id,category,title,url,use in extra:sources.append(dict(id=id,category=category,title=title,url=url,use=use,status='Official curriculum/documentation checked in prior conversation, 12 October. Course contents not completed by assistant. Durations are listed video time.'))
slides=[]
base={s['id']:s for s in draft['slides']}
topics={s['id']:s for s in research['topics']}
for id,minutes in [('14',2),('14B',2),('14C',1),('15',2),('14A',2),('15A',3),('15B',2),('16',2)]:
    if id in base:
        s=dict(base[id]);s['references']=[dict(title=k,url=draft['sources'][k]) for k in s['refs']]
    else:
        t=topics[id];s=dict(id=id,title=t['title'],bullets=t['copy'],notes=t['notes'],question='What would you test before implementing this?',anchor=t['placement'],layout=t['visual'],tie=t['example'],rationale='Connect task framing and cheap exploration to the later peer test.',references=[dict(title=r['title'],url=r['url']) for r in sources if r['id'] in t['refs']])
    s['min']=minutes;s['live']=True;s.pop('facilitation',None)
    s['readiness']='Copy ready; visual treatment below uses course-authored text or existing local activity. External media optional.'
    s['visual_plan']={
      '14':'Use the local fictional renamer result table, with the task beside it. Label as a teaching case.',
      '14B':'Typeset the original role–goal–benefit story beside three acceptance checks. No external image required.',
      '14C':'Proposed two simple wireframe arrangements for the same import operation; label as illustrative. Drawing remains a deck-generation task.',
      '15':'Use the same wireframe with source/destination/action/result groups. Add the short Qt layout excerpt as an implementation inset.',
      '14A':'Use selected Actor versus shared asset labels plus a before-action prediction. Refer back to the renamer; no claim of an observed Unreal run.',
      '15A':'Typeset contrasting proposed messages: Done versus a truthful changed/skipped/failed summary. Do not invent measured counts.',
      '15B':'Typeset Review → Apply → Verify → Recover; distinguish tested Undo from restore/reimport. Professional video remains optional.',
      '16':'Show the existing peer sheet and one goal-based task. Leave visible for four minutes of preparation.'}[id]
    slides.append(s)
byid={s['id']:s for s in slides}
for id,tid in [('14A','14A'),('16','16')]:
    t=topics[tid];byid[id].update(title=t['title'],bullets=t['copy'],notes=t['notes'])
    byid[id]['references'] += [dict(title=r['title'],url=r['url']) for r in sources if r['id'] in t['refs']]
byid['14A']['question']='What does the artist expect to change—and what actually changes?'
byid['16']['question']='What evidence would show that your change helped? What questions remain before testing?'
byid['15']['notes']+=' A layout manager keeps related labels and fields aligned as the window changes size. That is one technical way to support the grouping we just discussed. What questions do you have about applying this to your own panel?'
byid['15']['question']='Where would you look first? What questions do you have about grouping your own controls?'
byid['15A']['notes']+=' Match the interruption to the consequence: keep routine status near the work, and make consequential problems actionable.'
byid['15A']['references'].append(dict(title='Apple: Feedback',url='https://developer.apple.com/design/human-interface-guidelines/feedback'))
byid['14C']['notes']='Before coding, compare two rough arrangements for the same artist task. Include a result and an error state, not just the first screen. Paper is enough; Figma lets you connect screens to simulate the interaction. Neither proves the Unreal operation works. Where would you start in each version, and what would you expect next?'
optional=[s for s in draft['slides'] if not s['live']]
packet=dict(date='2026-10-13',scope='Consolidated Week 7 source and UI/UX slide-generation handoff',status='Content handoff; no deck generated; no live demo revalidated',live_minutes=16,prep_minutes=4,slides=slides,optional_slides=optional,sources=sources,visuals=visuals)
(ROOT/'deck_handoff.json').write_text(json.dumps(packet,ensure_ascii=False,indent=2),encoding='utf-8')
# Preserve every earlier tutorial and research link, with provenance; these are discovery records, not newly verified sources.
register={}
for rel in ['PrepNotes/Unreal_Tutorial_Index.html','PrepNotes/Research_Background.html','PrepNotes/Bridge_and_UX.html']:
    text=(W/rel).read_text(encoding='utf-8')
    for url,label in re.findall(r'<a\b[^>]*href="(https?://[^"]+)"[^>]*>(.*?)</a>',text,re.S):
        url=html.unescape(url);label=html.unescape(re.sub('<[^>]+>','',label)).strip()
        row=register.setdefault(url,dict(url=url,title=label,origin=[]))
        if rel not in row['origin']:row['origin'].append(rel)
for r in sources:
    row=register.setdefault(r['url'],dict(url=r['url'],title=r['title'],origin=[]));row['origin'].append('ProductionHandoff20261013/deck_handoff.json')
(ROOT/'all_source_links.json').write_text(json.dumps(list(register.values()),ensure_ascii=False,indent=2),encoding='utf-8')
css='''*{box-sizing:border-box}body{margin:0;background:#f6f5f9;color:#25222b;font:17px/1.6 Arial,sans-serif}main{max-width:1180px;margin:auto;padding:30px 24px}a{color:#594396}h1,h2,h3{line-height:1.25}nav,.bar{display:flex;gap:18px;flex-wrap:wrap}article,.panel{background:white;border:1px solid #d7d2df;border-radius:6px;padding:22px;margin:20px 0}blockquote{border-left:4px solid #029990;background:#f1f8f7;margin:12px 0;padding:12px 18px}.meta{font-size:14px;color:#625b69}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccc;padding:10px;text-align:left;vertical-align:top}pre{white-space:pre-wrap;background:#eeeaf4;padding:16px;overflow-wrap:anywhere}.bar{position:sticky;top:0;background:#f6f5f9;padding:12px 0}input,select{font:inherit;padding:7px;max-width:100%}img{max-width:100%;max-height:260px} [hidden]{display:none!important}@media(max-width:650px){main{padding:18px 12px}table{display:block;overflow:auto}}@media print{nav,.bar{display:none}article{break-inside:avoid}}'''
body=f'''<nav>{A('../PrepNotes/index.html','Prep plan')} {A('#route','Teaching route')} {A('#slides','Slide copy')} {A('#sources','Curated sources')} {A('#archive','Complete link register')}</nav><h1>Week 7 · source-to-slide production handoff</h1><p class="meta">13 October 2026 · Consolidates research through 12 October · Instructor review</p><p><strong>Use this as the next deck-generation input.</strong> The UI/UX route below merges the earlier draft and research supplement, preserving the assessment → overview → immediate peer-testing sequence. Unreal/Python material is indexed alongside it for the surrounding lesson. Earlier files remain source history.</p><p><strong>Ready:</strong> ordered slide copy, read-aloud notes, citations, technical illustration snippets, and existing activity handouts. <strong>Still pending:</strong> final slide composition, any new visual captures, demo rehearsal, and allocation of the extra ten minutes in the class agenda. The pack is not an offline mirror of external videos or paid courses.</p><section class="panel"><h2>Source authority and production rules</h2><ul><li>This page and deck_handoff.json are the consolidated UI/UX content proposal. Earlier six-slide timings are superseded for this proposed route.</li><li>Use the original course deck styling; IDs 14–16 remain stable anchors, with lettered insertions. No PowerPoint changed.</li><li>Use the current three-round activity sheets. The older two-page PrepNotes worksheet is historical background.</li><li>Professional advice, empirical research, and classroom applications are distinguished in the source register. No claimed productivity gains are imported into this class.</li><li>Core slides can be assembled without third-party video clips. Course-authored text layouts and the fictional renamer supply a usable fallback.</li></ul></section><h2 id="route">One teaching sequence</h2><table><tr><th>Block</th><th>Time</th><th>Student output</th></tr><tr><td>Tool assessment</td><td>8 min</td><td>Preserved first judgment, expected/observed result, initial priority</td></tr><tr><td>UI/UX overview</td><td>16 min</td><td>Reconsider or defend that judgment using a principle</td></tr><tr><td>Task preparation</td><td>4 min</td><td>Goal, inputs, success condition, protected scope, reset</td></tr><tr><td>Peer tests</td><td>35 min</td><td>3-minute briefing + three ten-minute reciprocal rounds + two one-minute switches</td></tr><tr><td>Synthesis</td><td>5 min</td><td>One change and a retest</td></tr></table><p>68 minutes total. Put the break before the assessment. Retaining the confirmed 6:00 finish requires starting this sequence at 4:52 and reallocating ten minutes earlier; that allocation is not yet settled. No presenter slot, break, or class finish is changed by this document.</p><p>During each slide, reserve roughly its final 20–30 seconds for the visible prompt. Slides 15 and 16 explicitly invite students’ own questions. Protect the four-minute task-preparation window.</p><h2>Surrounding Unreal/Python content</h2><table><tr><th>Purpose</th><th>Use</th><th>Readiness</th></tr><tr><td>Maya → Unreal transition</td><td>{A('../PrepNotes/Bridge_and_UX.html','Bridge run sheet')} + {A('https://isaacoster.artstation.com/projects/Dvdrke','Oster import/export')}</td><td>Written plan; rehearse import, revision, same-asset reimport, and failure recovery in the teaching engine.</td></tr><tr><td>Unreal data model and Python</td><td>{A('../PrepNotes/source_index.html','Existing source notes')} + {A('../PrepNotes/Unreal_Tutorial_Index.html','Full tutorial library')}</td><td>Reuse completed study. Distinguish disk/asset paths, Actor/Component/asset, and selection scope.</td></tr><tr><td>Optional material extension</td><td>{A('https://isaacoster.artstation.com/projects/qeAwqe','Texture Utility')} + {A('https://isaacoster.artstation.com/projects/xDB8zR','Asset Setup')}</td><td>Choose one operation. This handoff does not establish that a new material demo is implemented.</td></tr><tr><td>Later content</td><td>{A('../PrepNotes/Unreal_Tutorial_Index.html#later','PCG, procedural modeling, landscapes, Niagara, and other later topics')}</td><td>Retained for later teaching, not added to Week 7.</td></tr></table><h2 id="slides">Consolidated live slide copy</h2><p>Proposed order: 14 → 14B → 14C → 15 → 14A → 15A → 15B → 16. Total teaching time: 16 minutes. {A('../UXDraft20261012/index.html','Earlier current-versus-proposed slide review')} preserves the actual historical slide renders and text.</p>'''
for s in slides:
    body+=f'<article><p class="meta">Anchor {E(s["id"])} · {s["min"]} min · {E(s["readiness"])}</p><h2>{E(s["title"])}</h2><p><strong>Edit:</strong> {E(s["anchor"])}</p><ul>'+''.join('<li>'+E(x)+'</li>' for x in s['bullets'])+f'</ul><p><strong>Visible prompt:</strong> {E(s["question"])}</p><h3>Read aloud</h3><blockquote>{E(s["notes"])}</blockquote><p><strong>Visual/layout:</strong> {E(s["visual_plan"])}</p><p><strong>Rationale:</strong> {E(s["rationale"])}</p><p><strong>Sources / Explore further:</strong> '+ ' · '.join(A(x['url'],x['title']) for x in s['references'])+'</p></article>'
body+='''<section class="panel"><h2>Qt implementation insets · original illustrative snippets</h2><p>Use only a small excerpt next to the interface decision it explains. These fragments require surrounding PySide6 setup and are not executed demonstrations or a complete importer. Qt is a Python desktop-tool example; Editor Utility Widgets are the Unreal-native comparison.</p><h3>Slide 15: labels and fields belong together</h3><pre>form = QFormLayout()
form.addRow("Source file", source_field)
form.addRow("Unreal destination", destination_field)</pre><p>A layout manager expresses relationships and handles placement. It does not decide whether the labels or workflow are understandable.</p><h3>Slide 15A: changes can update feedback before execution</h3><pre>source_field.textChanged.connect(update_preview)
import_button.clicked.connect(run_import)</pre><p>The first connection lets an input change trigger feedback; the second connects the action to the operation. Validation must explain a problem and the operation must still validate its inputs when it runs. Do not promise responsive progress from a blocking long task without testing the implementation.</p><p>Optional 15B example: a file dialog helps select a path, while a result list identifies affected assets. Framework controls do not automatically guarantee accessibility or a usable recovery path.</p></section>'''
body+='<h2>Activity deployment</h2><ul>'+''.join('<li>'+A('../ActivitiesDraft20261012/'+p,t)+'</li>' for p,t in [('index.html','Facilitation and rotations'),('group-sheet.html','Group assessment: print one per group'),('reveal.html','Fictional result: project after predictions'),('peer-sheet.html','Short peer review: three reviews per student'),('reflection.html','Reflection and synthesis')])+'</ul><p>Preserve initial judgments before giving heuristic vocabulary. The recorded renamer case reveals functional errors; it does not prove a live user was confused. Keep the tool version stable through the three peer rounds; record emergency changes and plan a subsequent retest.</p>'
body+='<h2>Visual production register</h2><p>Exact credits and reuse notes carried forward. Links and previews are not a redistribution license. V1–V3 require source-page inspection after their image endpoints returned 403. Use the text-based layouts above if third-party media is unavailable.</p>'
for v in visuals:
    url=v['url'] if v['url'].startswith('http') else '../ActivitiesDraft20261012/reveal.html'
    body+=f'<details><summary>{E(v["id"]+": "+v["title"])}</summary><p>{E(v["use"])}</p><p>{E(v["credit"])}</p><p>{E(v["rights"])}</p><p>{A(url,"Original visual / walkthrough")}</p></details>'
body+='<p>Additional linked candidates: Jodie Azhar PDF pages 32–35; Dow et al. Figure 1 on PDF page 1; Apple chapter excerpts; Figma connected-frame illustrations. These are source locations, not exported slide assets. Their context and links are in the source records below.</p><h2>Before deck generation</h2><ol><li>Use the consolidated eight-slide route and existing original deck theme.</li><li>Choose course-authored text/wireframe treatments by default; only add inspected, credited external visuals.</li><li>Keep the full Qt and Blueprint courses in instructor preparation. No purchase or course completion is required for these slides.</li><li>Rehearse the actual Maya/Unreal handoff and any Qt example separately; capture only genuine results.</li><li>Resolve the agenda allocation before printing final clock times on slides.</li></ol><h2 id="sources">Curated source register</h2><div class="bar"><label>Search <input id="q" type="search" placeholder="Qt, testing, GDC…"></label><label>Show <select id="kind"><option value="all">All curated sources</option><option value="free">Exclude optional paid study</option><option value="paid">Optional paid study</option></select></label></div>'
for r in sources:body+=f'<article class="source" data-paid="{str(r["category"]=="Optional paid study").lower()}"><p class="meta">{E(r["id"])} · {E(r["category"])}</p><h3>{A(r["url"],r["title"])}</h3><p>{E(r.get("credit",""))}</p><p>{E(r["use"])}</p><p class="meta">{E(r["status"])}</p></article>'
body+=f'<h2 id="archive">Complete earlier link register · {len(register)} distinct URLs</h2><p>Includes earlier research leads, alternate courses, and later topics. Presence here is not an endorsement, an access check, or a claim that the source was read. Use the curated register above for slide citations.</p><details><summary>Browse every preserved link and its source file</summary>'
for r in register.values():body+='<p>'+A(r['url'],r['title'] or r['url'])+'<br><span class="meta">'+E(' · '.join(r['origin']))+'</span></p>'
body+='</details><p>'+A('deck_handoff.json','Structured deck-generation input')+' · '+A('all_source_links.json','Complete source-link register')+' · '+A('../UXDraft20261012/research.html','Detailed research history')+'</p>'
js="const q=document.querySelector('#q'),k=document.querySelector('#kind');function filter(){document.querySelectorAll('.source').forEach(c=>c.hidden=!(k.value==='all'||(k.value==='paid')===(c.dataset.paid==='true'))||!c.textContent.toLowerCase().includes(q.value.toLowerCase()));}q.oninput=filter;k.onchange=filter;"
body='<section class="panel"><h2>Current production result</h2><p><a href="../RefinedDeck20261013/index.html">Refined deck, slide previews and citations</a> · <a href="source_audit.html">Complete source audit, including Python and Unreal</a></p><p>The deck is now assembled. The earlier handoff below is retained as source history; its pending-composition statements are superseded. Demo rehearsal and the proposed timetable remain instructor preparation items.</p></section>'+body
(ROOT/'index.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Week 7 · production handoff</title><style>{css}</style></head><body><main>{body}</main><script>{js}</script></body></html>',encoding='utf-8')
assert sum(s['min'] for s in slides)==16
